const CANONICAL_MAC_V1_RECEIPT='/Users/lsb/.config/ai-brain/mac-skill-bundle-install-receipt.json';
const CANONICAL_MAC_V1_RECEIPT_ROOT='/Users/lsb/.config/ai-brain';
const CANONICAL_MAC_V2_RECEIPT='/Users/lsb/AI-Brain/niannian-ai-canonical-local/output/mac-employee-training/mac-skill-bundle-v2-install-receipt.json';
