    await fsp.mkdir(installRoot,{recursive:true});await fsp.mkdir(preparedRoot,{recursive:true});await fsp.mkdir(originalsRoot,{recursive:true});await fsp.mkdir(backupTreeRoot,{recursive:true});
    let preparedIndex=0;for(const item of verified.manifest.files.filter(item=>item.path.startsWith('skills/'))){preparedIndex+=1;const content=await verified.zip.file(item.path).async('nodebuffer');const target=path.join(preparedRoot,...item.path.split('/').slice(1));await atomicBytes(target,content);if(Number(options.failDuringPrepareAt)===preparedIndex)throw new Error('mac_skill_bundle_injected_prepare_failure:'+preparedIndex);}
    const installedTop=[];for(const entry of await fsp.readdir(installRoot,{withFileTypes:true})){const target=path.join(installRoot,entry.name);const stats=await lstatImpl(target);if(stats.isSymbolicLink())throw new Error('mac_skill_bundle_installed_symlink_rejected:'+entry.name);if(!stats.isDirectory())throw new Error('mac_skill_bundle_installed_special_top_level_rejected:'+entry.name);installedTop.push(entry.name);}const classifiedTop=classifyTopLevelNames(installedTop,verified.manifest.skills,'mac_skill_bundle_installed_top_level',{requireManagedPresent:false});journal.unmanaged_top_level_entries=classifiedTop.unmanaged_top_level_entries;journal.unmanaged_top_level_before=await unmanagedDirectoryEvidence(installRoot,journal.unmanaged_top_level_entries,lstatImpl);
    const beforeRows=[];let backupIndex=0;for(const skill of verified.manifest.skills){const source=path.join(preparedRoot,skill);await fsp.access(path.join(source,'SKILL.md'));await assertRegularTree(source,'mac_skill_bundle_stage_symlink_rejected',lstatImpl);const target=path.join(installRoot,skill);if(await exists(target)){await assertRegularTree(target,'mac_skill_bundle_installed_symlink_rejected',lstatImpl);for(const item of await treeRows(target))beforeRows.push({path:skill+'/'+item.path,bytes:item.bytes,sha256:item.sha256});await fsp.cp(target,path.join(backupTreeRoot,skill),{recursive:true,force:false,errorOnExist:true});backupIndex+=1;if(Number(options.failDuringBackupAt)===backupIndex)throw new Error('mac_skill_bundle_injected_backup_failure:'+backupIndex);}}
    journal.pre_install_tree_sha256=treeIdentity(beforeRows);journal.before_tree_sha256=journal.pre_install_tree_sha256;const backupRows=[];for(const skill of verified.manifest.skills)for(const item of await treeRows(path.join(backupTreeRoot,skill)))backupRows.push({path:skill+'/'+item.path,bytes:item.bytes,sha256:item.sha256});journal.backup_tree_sha256=options.forceBackupIdentityMismatch?'0'.repeat(64):treeIdentity(backupRows);journal.backup_matches_pre_install_tree=journal.backup_tree_sha256===journal.pre_install_tree_sha256;if(!journal.backup_matches_pre_install_tree)throw new Error('mac_skill_bundle_backup_tree_identity_mismatch');
